    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            D[i, j] = D[j, i] = d

    def feasible(lam):
        if np.any(border < lam - 1e-12):
            return False
        for i in range(n):
            for j in range(i + 1, n):
                if 2 * lam > D[i, j] + 1e-12:
                    return False
        return True

