def _max_sum_radii(centers):
    """Robust max-sum radii for fixed centers via max-min fair water filling."""
    centers = np.asarray(centers, float)
    n = centers.shape[0]
    border = np.minimum(np.minimum(centers[:, 0], 1 - centers[:, 0]),
                        np.minimum(centers[:, 1], 1 - centers[:, 1]))
    diff = centers[:, None, :] - centers[None, :, :]
    D = np.sqrt((diff ** 2).sum(-1))
    np.fill_diagonal(D, np.inf)

    def feasible(lam):
        if border.min() < lam - 1e-12:
            return False
        return (D.min() / 2) >= lam - 1e-12

    lo, hi = 0.0, min(float(border.min()), float(D.min()) / 2)
    for _ in range(50):
        mid = (lo + hi) / 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    r = np.full(n, lo)
    for _ in range(3000):
        head = np.minimum(border - r, (D - r[None, :] - r[:, None]).min(1))
        head = np.where(np.isinf(head), border - r, head)
        i = int(np.argmax(head))
        if head[i] < 1e-9:
            break
        r[i] += min(head[i], 0.01)
    np.maximum(r, 0, out=r)
    return r


