    """5x5 grid of points inset by margin, plus a center point."""
    xs = np.linspace(margin, 1 - margin, 5)
    ys = np.linspace(margin, 1 - margin, 5)
    pts = []
    for y in ys:
        for x in xs:
            pts.append([x, y])
    pts.append([cx, cy])
    return np.array(pts[:26])


